import os
import sqlite3
from datetime import datetime
from functools import wraps
from flask import (
    Flask, render_template, request, redirect,
    url_for, session, flash, g, abort
)
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY", "change-this-in-production-please")

DATABASE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "notes.db")

# ---------------------------------------------------------------------------
# Database helpers
# ---------------------------------------------------------------------------

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    """Create tables and seed a default user if none exist."""
    db = sqlite3.connect(DATABASE)
    db.executescript(
        """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS patients (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        -- Append-only: rows are NEVER updated or deleted.
        CREATE TABLE IF NOT EXISTS notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            patient_id INTEGER NOT NULL,
            author TEXT NOT NULL,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL,
            supersedes_id INTEGER,  -- link to the note this version replaces (NULL = original)
            FOREIGN KEY (patient_id) REFERENCES patients(id),
            FOREIGN KEY (supersedes_id) REFERENCES notes(id)
        );
        """
    )
    # Seed default user (physio / changeme) if empty
    row = db.execute("SELECT COUNT(*) AS c FROM users").fetchone()
    if row[0] == 0:
        db.execute(
            "INSERT INTO users (username, password_hash) VALUES (?, ?)",
            ("physio", generate_password_hash("changeme")),
        )
    db.commit()
    db.close()


# ---------------------------------------------------------------------------
# Auth
# ---------------------------------------------------------------------------

def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not session.get("user"):
            return redirect(url_for("login"))
        return f(*args, **kwargs)
    return wrapper


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        db = get_db()
        user = db.execute(
            "SELECT * FROM users WHERE username = ?", (username,)
        ).fetchone()
        if user and check_password_hash(user["password_hash"], password):
            session["user"] = username
            return redirect(url_for("patients"))
        flash("Invalid credentials", "error")
    return render_template("login.html")


@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("login"))


# ---------------------------------------------------------------------------
# Patients
# ---------------------------------------------------------------------------

@app.route("/")
@login_required
def patients():
    db = get_db()
    rows = db.execute(
        """
        SELECT p.*, 
               (SELECT COUNT(*) FROM notes n WHERE n.patient_id = p.id) AS note_count
        FROM patients p
        ORDER BY p.name COLLATE NOCASE
        """
    ).fetchall()
    return render_template("patients.html", patients=rows)


@app.route("/patients/new", methods=["GET", "POST"])
@login_required
def new_patient():
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        if not name:
            flash("Patient name is required", "error")
        else:
            db = get_db()
            cur = db.execute(
                "INSERT INTO patients (name, created_at) VALUES (?, ?)",
                (name, datetime.utcnow().isoformat()),
            )
            db.commit()
            return redirect(url_for("patient", patient_id=cur.lastrowid))
    return render_template("new_patient.html")


@app.route("/patients/<int:patient_id>")
@login_required
def patient(patient_id):
    db = get_db()
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if not patient:
        abort(404)
    notes = db.execute(
        "SELECT * FROM notes WHERE patient_id = ? ORDER BY created_at ASC",
        (patient_id,),
    ).fetchall()
    # Group by "thread": each root note with its versions, newest first
    return render_template("patient.html", patient=patient,
                           notes=notes, now=datetime.utcnow)


# ---------------------------------------------------------------------------
# Notes (append-only)
# ---------------------------------------------------------------------------

@app.route("/patients/<int:patient_id>/notes", methods=["POST"])
@login_required
def add_note(patient_id):
    """Create a new note. If `supersedes_id` is provided, this is an
    edit of a previous note — a brand new row is inserted that points
    to the earlier one. The earlier note is NEVER modified."""
    db = get_db()
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if not patient:
        abort(404)

    body = request.form.get("body", "").strip()
    supersedes = request.form.get("supersedes_id", type=int)

    if not body:
        flash("Note cannot be empty", "error")
        return redirect(url_for("patient", patient_id=patient_id))

    # If editing, verify the parent note exists for this patient
    if supersedes is not None:
        parent = db.execute(
            "SELECT id FROM notes WHERE id = ? AND patient_id = ?",
            (supersedes, patient_id),
        ).fetchone()
        if not parent:
            abort(400)

    db.execute(
        """INSERT INTO notes (patient_id, author, body, created_at, supersedes_id)
           VALUES (?, ?, ?, ?, ?)""",
        (patient_id, session["user"], body,
         datetime.utcnow().isoformat(), supersedes),
    )
    db.commit()
    flash("Note saved", "success")
    return redirect(url_for("patient", patient_id=patient_id))


@app.errorhandler(404)
def not_found(e):
    return "Not found", 404


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    init_db()
    app.run(host="127.0.0.1", port=5000, debug=True)
